use std::collections::HashMap;
use std::fs;
use std::io::{self, Read, Write, BufWriter};
use std::path::Path;
use std::f32::consts::PI;

// ============ OBJ/MTL Parser ============

#[derive(Debug, Clone)]
struct Material {
    name: String,
    kd: [f32; 3], // diffuse color
}

#[derive(Debug, Clone)]
struct Face {
    vertices: Vec<usize>,   // 0-indexed vertex positions
    normals: Vec<usize>,    // 0-indexed normal indices
    material_idx: usize,
}

#[derive(Debug)]
struct Model {
    vertices: Vec<[f32; 3]>,
    normals: Vec<[f32; 3]>,
    faces: Vec<Face>,
    materials: Vec<Material>,
}

fn load_mtl(path: &str) -> Vec<Material> {
    let content = fs::read_to_string(path)
        .expect(&format!("Expected to have materials.: OpenFileFailed"));

    let mut materials = Vec::new();
    let mut current_name = String::new();
    let mut current_kd = [0.0f32; 3];

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("newmtl ") {
            if !current_name.is_empty() {
                materials.push(Material { name: current_name.clone(), kd: current_kd });
            }
            current_name = line[7..].to_string();
            current_kd = [0.0, 0.0, 0.0];
        } else if line.starts_with("Kd ") {
            let parts: Vec<f32> = line[3..].split_whitespace()
                .filter_map(|x| x.parse().ok())
                .collect();
            if parts.len() >= 3 {
                current_kd = [parts[0], parts[1], parts[2]];
            }
        }
    }
    if !current_name.is_empty() {
        materials.push(Material { name: current_name, kd: current_kd });
    }

    materials
}

fn load_obj(path: &str) -> Model {
    let content = fs::read_to_string(path)
        .expect("Failed to read OBJ file");

    let obj_dir = Path::new(path).parent().unwrap_or(Path::new("."));

    let mut vertices: Vec<[f32; 3]> = Vec::new();
    let mut normals: Vec<[f32; 3]> = Vec::new();
    let mut faces: Vec<Face> = Vec::new();
    let mut materials: Vec<Material> = Vec::new();
    let mut material_map: HashMap<String, usize> = HashMap::new();
    let mut current_material: usize = 0;

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("mtllib ") {
            let mtl_file = line[7..].trim();
            let mtl_path = obj_dir.join(mtl_file);
            let loaded = load_mtl(mtl_path.to_str().unwrap());
            for mat in loaded {
                let idx = materials.len();
                material_map.insert(mat.name.clone(), idx);
                materials.push(mat);
            }
        } else if line.starts_with("v ") {
            let parts: Vec<f32> = line[2..].split_whitespace()
                .filter_map(|x| x.parse().ok())
                .collect();
            if parts.len() >= 3 {
                vertices.push([parts[0], parts[1], parts[2]]);
            }
        } else if line.starts_with("vn ") {
            let parts: Vec<f32> = line[3..].split_whitespace()
                .filter_map(|x| x.parse().ok())
                .collect();
            if parts.len() >= 3 {
                normals.push([parts[0], parts[1], parts[2]]);
            }
        } else if line.starts_with("usemtl ") {
            let mat_name = line[7..].trim();
            current_material = *material_map.get(mat_name).unwrap_or(&0);
        } else if line.starts_with("f ") {
            let tokens: Vec<&str> = line[2..].split_whitespace().collect();
            let mut verts = Vec::new();
            let mut norms = Vec::new();
            for token in &tokens {
                let parts: Vec<&str> = token.split('/').collect();
                if parts.len() >= 1 {
                    if let Ok(v) = parts[0].parse::<i32>() {
                        let vi = if v < 0 { (vertices.len() as i32 + v) as usize } else { (v - 1) as usize };
                        verts.push(vi);
                    }
                }
                if parts.len() >= 3 {
                    if let Ok(n) = parts[2].parse::<i32>() {
                        let ni = if n < 0 { (normals.len() as i32 + n) as usize } else { (n - 1) as usize };
                        norms.push(ni);
                    }
                }
            }
            if verts.len() >= 3 {
                faces.push(Face {
                    vertices: verts,
                    normals: norms,
                    material_idx: current_material,
                });
            }
        }
    }

    Model { vertices, normals, faces, materials }
}

// ============ Math Utilities ============

fn cross(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    [
        a[1]*b[2] - a[2]*b[1],
        a[2]*b[0] - a[0]*b[2],
        a[0]*b[1] - a[1]*b[0],
    ]
}

fn sub(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    [a[0]-b[0], a[1]-b[1], a[2]-b[2]]
}

fn dot(a: [f32; 3], b: [f32; 3]) -> f32 {
    a[0]*b[0] + a[1]*b[1] + a[2]*b[2]
}

fn normalize(a: [f32; 3]) -> [f32; 3] {
    let len = (a[0]*a[0] + a[1]*a[1] + a[2]*a[2]).sqrt();
    if len > 1e-10 { [a[0]/len, a[1]/len, a[2]/len] } else { a }
}

fn rotate_y(v: [f32; 3], theta: f32) -> [f32; 3] {
    let (s, c) = (theta.sin(), theta.cos());
    [v[0]*c + v[2]*s, v[1], -v[0]*s + v[2]*c]
}

fn rotate_x(v: [f32; 3], theta: f32) -> [f32; 3] {
    let (s, c) = (theta.sin(), theta.cos());
    [v[0], v[1]*c - v[2]*s, v[1]*s + v[2]*c]
}

fn rotate_z(v: [f32; 3], theta: f32) -> [f32; 3] {
    let (s, c) = (theta.sin(), theta.cos());
    [v[0]*c - v[1]*s, v[0]*s + v[1]*c, v[2]]
}

fn apply_rotation(v: [f32; 3], rx: f32, ry: f32, rz: f32) -> [f32; 3] {
    // Apply rotations: x, then y, then z
    let v = rotate_x(v, rx);
    let v = rotate_y(v, ry);
    let v = rotate_z(v, rz);
    v
}

// ============ Rendering ============

const SHADE_CHARS: &[char] = &['.', ':', '-', '=', '+', '*', '#', '%'];

fn shade_char(dot_val: f32) -> char {
    if dot_val <= 0.0 {
        return ' '; // back-face culled
    }
    let idx = ((dot_val * 10.0) as i32 - 1).max(0).min(7) as usize;
    SHADE_CHARS[idx]
}

fn kd_to_rgb(kd: [f32; 3]) -> [u8; 3] {
    [
        (kd[0] * 255.0) as u8,
        (kd[1] * 255.0) as u8,
        (kd[2] * 255.0) as u8,
    ]
}

struct FrameBuffer {
    width: usize,
    height: usize,
    colors: Vec<Option<[u8; 3]>>,
    chars: Vec<char>,
    zbuf: Vec<f32>,
}

impl FrameBuffer {
    fn new(width: usize, height: usize) -> Self {
        let n = width * height;
        FrameBuffer {
            width,
            height,
            colors: vec![None; n],
            chars: vec![' '; n],
            zbuf: vec![f32::INFINITY; n],
        }
    }

    fn set_pixel(&mut self, x: i32, y: i32, z: f32, color: [u8; 3], ch: char) {
        if x < 0 || y < 0 || x >= self.width as i32 || y >= self.height as i32 {
            return;
        }
        let idx = y as usize * self.width + x as usize;
        if z < self.zbuf[idx] {
            self.zbuf[idx] = z;
            self.colors[idx] = Some(color);
            self.chars[idx] = ch;
        }
    }
}

fn compute_scale_and_center(model: &Model, rx: f32, ry: f32, rz: f32, width: usize, height: usize) -> (f32, f32, f32) {
    // Compute bounding box of rotated model
    let mut min_x = f32::INFINITY;
    let mut max_x = f32::NEG_INFINITY;
    let mut min_y = f32::INFINITY;
    let mut max_y = f32::NEG_INFINITY;

    for v in &model.vertices {
        let rv = apply_rotation(*v, rx, ry, rz);
        min_x = min_x.min(rv[0]);
        max_x = max_x.max(rv[0]);
        min_y = min_y.min(rv[1]);
        max_y = max_y.max(rv[1]);
    }

    let model_w = max_x - min_x;
    let model_h = max_y - min_y;

    let w = width as f32;
    let h = height as f32;

    // Scale: fit model in image, with aspect ratio correction (1 terminal row = 2 pixels tall)
    // The image is w columns wide and h rows tall
    // model should fit: scale_x = (w-1)/model_w, scale_y = scale_x/2 in rows
    // Check if height limits: model_h * scale_y_rows <= h-1
    // scale_y_rows = (h-1)/model_h, scale_x = scale_y_rows * 2 = (h-1)*2/model_h

    let scale_from_w = if model_w > 0.0 { (w - 1.0) / model_w } else { 1.0 };
    let scale_from_h = if model_h > 0.0 { (h - 1.0) * 2.0 / model_h } else { 1.0 };

    let scale = scale_from_w.min(scale_from_h);

    // Center
    let cx = (min_x + max_x) / 2.0;
    let cy = (min_y + max_y) / 2.0;

    (scale, cx, cy)
}

fn render_model(model: &Model, rx: f32, ry: f32, rz: f32, width: usize, height: usize) -> FrameBuffer {
    let mut fb = FrameBuffer::new(width, height);

    let (scale, model_cx, model_cy) = compute_scale_and_center(model, rx, ry, rz, width, height);

    let screen_cx = (width as f32 - 1.0) / 2.0;
    let screen_cy = (height as f32 - 1.0) / 2.0;

    // Light direction: toward viewer (0, 0, 1)
    let light = [0.0f32, 0.0, 1.0];

    for face in &model.faces {
        if face.vertices.len() < 3 {
            continue;
        }

        // Get material
        let mat = &model.materials[face.material_idx.min(model.materials.len() - 1)];
        let color = kd_to_rgb(mat.kd);

        // Get face normal (from OBJ, or compute)
        let face_normal = if !face.normals.is_empty() {
            // Use OBJ normal, rotated
            let n = model.normals[face.normals[0].min(model.normals.len() - 1)];
            apply_rotation(n, rx, ry, rz)
        } else {
            // Compute from vertices
            let v0 = apply_rotation(model.vertices[face.vertices[0]], rx, ry, rz);
            let v1 = apply_rotation(model.vertices[face.vertices[1]], rx, ry, rz);
            let v2 = apply_rotation(model.vertices[face.vertices[2]], rx, ry, rz);
            let e1 = sub(v1, v0);
            let e2 = sub(v2, v0);
            normalize(cross(e1, e2))
        };

        let dot_nl = dot(face_normal, light);

        // Back-face culling
        if dot_nl <= 0.0 {
            continue;
        }

        let ch = shade_char(dot_nl);

        // Triangulate the face (fan triangulation)
        let verts: Vec<[f32; 3]> = face.vertices.iter()
            .map(|&vi| apply_rotation(model.vertices[vi.min(model.vertices.len()-1)], rx, ry, rz))
            .collect();

        for i in 1..verts.len()-1 {
            rasterize_triangle(
                &mut fb,
                verts[0], verts[i], verts[i+1],
                scale, model_cx, model_cy, screen_cx, screen_cy,
                color, ch
            );
        }
    }

    fb
}

fn project(v: [f32; 3], scale: f32, model_cx: f32, model_cy: f32, screen_cx: f32, screen_cy: f32) -> (f32, f32, f32) {
    let sx = (v[0] - model_cx) * scale + screen_cx;
    let sy = -(v[1] - model_cy) * scale / 2.0 + screen_cy;  // Y flipped, /2 for aspect
    (sx, sy, v[2])
}

fn rasterize_triangle(
    fb: &mut FrameBuffer,
    v0: [f32; 3], v1: [f32; 3], v2: [f32; 3],
    scale: f32, model_cx: f32, model_cy: f32, screen_cx: f32, screen_cy: f32,
    color: [u8; 3], ch: char,
) {
    let (x0, y0, z0) = project(v0, scale, model_cx, model_cy, screen_cx, screen_cy);
    let (x1, y1, z1) = project(v1, scale, model_cx, model_cy, screen_cx, screen_cy);
    let (x2, y2, z2) = project(v2, scale, model_cx, model_cy, screen_cx, screen_cy);

    // Bounding box
    let min_x = x0.min(x1).min(x2).floor() as i32;
    let max_x = x0.max(x1).max(x2).ceil() as i32;
    let min_y = y0.min(y1).min(y2).floor() as i32;
    let max_y = y0.max(y1).max(y2).ceil() as i32;

    let min_x = min_x.max(0);
    let max_x = max_x.min(fb.width as i32 - 1);
    let min_y = min_y.max(0);
    let max_y = max_y.min(fb.height as i32 - 1);

    // Area of triangle (for barycentric coordinates)
    let denom = (y1 - y2) * (x0 - x2) + (x2 - x1) * (y0 - y2);
    if denom.abs() < 1e-10 {
        return;
    }

    for py in min_y..=max_y {
        for px in min_x..=max_x {
            let px_f = px as f32 + 0.5;
            let py_f = py as f32 + 0.5;

            // Barycentric coordinates
            let w0 = ((y1 - y2) * (px_f - x2) + (x2 - x1) * (py_f - y2)) / denom;
            let w1 = ((y2 - y0) * (px_f - x2) + (x0 - x2) * (py_f - y2)) / denom;
            let w2 = 1.0 - w0 - w1;

            if w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0 {
                // Interpolate z
                let z = w0 * z0 + w1 * z1 + w2 * z2;
                fb.set_pixel(px, py, z, color, ch);
            }
        }
    }
}

// ============ Output ============

fn output_ansi<W: Write>(writer: &mut W, fb: &FrameBuffer) {
    let w = fb.width;
    let h = fb.height;

    for y in 0..h {
        for x in 0..w {
            let idx = y * w + x;
            let (r, g, b, fg_r, fg_g, fg_b, ch) = match fb.colors[idx] {
                Some(c) => (25u8, 25u8, 25u8, c[0], c[1], c[2], fb.chars[idx]),
                None => (25u8, 25u8, 25u8, 0u8, 0u8, 0u8, ' '),
            };

            if x == w - 1 && y < h - 1 {
                // Last column: print newline as character
                write!(writer, "\x1b[48;2;{};{};{}m\x1b[38;2;{};{};{}m\n\x1b[49m\x1b[39m",
                    r, g, b, fg_r, fg_g, fg_b).unwrap();
            } else {
                write!(writer, "\x1b[48;2;{};{};{}m\x1b[38;2;{};{};{}m{}\x1b[49m\x1b[39m",
                    r, g, b, fg_r, fg_g, fg_b, ch).unwrap();
            }
        }
    }
}

fn output_html_frame<W: Write>(writer: &mut W, fb: &FrameBuffer) {
    let w = fb.width;
    let h = fb.height;

    for y in 0..h {
        for x in 0..w {
            let idx = y * w + x;
            let (r, g, b, ch) = match fb.colors[idx] {
                Some(c) => (c[0], c[1], c[2], fb.chars[idx]),
                None => (0u8, 0u8, 0u8, ' '),
            };
            write!(writer, "<span style=\"color:rgb({},{},{})\">{}",
                r, g, b, ch).unwrap();
        }
        if y < h - 1 {
            writeln!(writer, "").unwrap();
        }
    }
}

fn output_terminal<W: Write>(writer: &mut W, fb: &FrameBuffer) {
    // Terminal mode output (uses ANSI with 24-bit color)
    output_ansi(writer, fb);
}

// ============ Main ============

fn main() {
    let args: Vec<String> = std::env::args().collect();

    // Parse arguments manually (matching clap behavior from help output)
    // USAGE: executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]
    // FLAGS: -h, --help; -b; -V, --version
    // OPTIONS: -x/--yaw, -y/--pitch, -z/--roll
    // SUBCOMMAND: image

    let mut rx = 0.0f32;
    let mut ry = 0.0f32;
    let mut rz = 0.0f32;
    let mut no_color = false;
    let mut input_files: Vec<String> = Vec::new();
    let mut subcommand: Option<String> = None;
    let mut img_width: Option<usize> = None;
    let mut img_height: Option<usize> = None;
    let mut webify_frames: Option<usize> = None;

    let mut i = 1;
    let mut in_subcommand = false;

    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "--help" | "-h" => {
                print_help();
                return;
            }
            "--version" | "-V" => {
                println!("Sloth 0.1");
                return;
            }
            "-b" => {
                no_color = true;
            }
            "-x" | "--yaw" => {
                i += 1;
                if i < args.len() {
                    rx = args[i].parse().unwrap_or(0.0);
                }
            }
            "-y" | "--pitch" => {
                i += 1;
                if i < args.len() {
                    ry = args[i].parse().unwrap_or(0.0);
                }
            }
            "-z" | "--roll" => {
                i += 1;
                if i < args.len() {
                    rz = args[i].parse().unwrap_or(0.0);
                }
            }
            "image" if !in_subcommand && input_files.len() > 0 => {
                subcommand = Some("image".to_string());
                in_subcommand = true;
            }
            "help" => {
                print_help();
                return;
            }
            _ if in_subcommand => {
                match arg.as_str() {
                    "--help" => {
                        print_image_help();
                        return;
                    }
                    "-b" => {
                        no_color = true;
                    }
                    "-w" => {
                        i += 1;
                        if i < args.len() {
                            img_width = args[i].parse().ok();
                        }
                    }
                    "-h" => {
                        i += 1;
                        if i < args.len() {
                            img_height = args[i].parse().ok();
                        }
                    }
                    "-j" | "--webify" => {
                        i += 1;
                        if i < args.len() {
                            webify_frames = args[i].parse().ok();
                        }
                    }
                    "-x" | "--yaw" => {
                        i += 1;
                        if i < args.len() {
                            rx = args[i].parse().unwrap_or(0.0);
                        }
                    }
                    "-y" | "--pitch" => {
                        i += 1;
                        if i < args.len() {
                            ry = args[i].parse().unwrap_or(0.0);
                        }
                    }
                    "-z" | "--roll" => {
                        i += 1;
                        if i < args.len() {
                            rz = args[i].parse().unwrap_or(0.0);
                        }
                    }
                    _ => {}
                }
            }
            _ => {
                input_files.push(arg.clone());
            }
        }
        i += 1;
    }

    if input_files.is_empty() {
        print_help();
        return;
    }

    // Load model(s)
    let mut combined_model = Model {
        vertices: Vec::new(),
        normals: Vec::new(),
        faces: Vec::new(),
        materials: Vec::new(),
    };

    for filepath in &input_files {
        // Handle space-separated files in one argument
        for path in filepath.split_whitespace() {
            let model = load_obj(path);
            let vert_offset = combined_model.vertices.len();
            let norm_offset = combined_model.normals.len();
            let mat_offset = combined_model.materials.len();

            for v in model.vertices { combined_model.vertices.push(v); }
            for n in model.normals { combined_model.normals.push(n); }
            for mut f in model.faces {
                f.vertices = f.vertices.iter().map(|&v| v + vert_offset).collect();
                f.normals = f.normals.iter().map(|&n| n + norm_offset).collect();
                f.material_idx += mat_offset;
                combined_model.faces.push(f);
            }
            for m in model.materials { combined_model.materials.push(m); }
        }
    }

    let stdout = io::stdout();
    let mut writer = BufWriter::new(stdout.lock());

    match subcommand.as_deref() {
        Some("image") => {
            let w = img_width.expect("Width is required for image subcommand");
            let h = img_height.unwrap_or(w);

            if let Some(n_frames) = webify_frames {
                // Webify mode
                write!(writer, "let frames = [\n").unwrap();
                for frame_idx in 0..n_frames {
                    let theta = 2.0 * PI * frame_idx as f32 / n_frames as f32;
                    let frame_ry = ry + theta;

                    let fb = render_model(&combined_model, rx, frame_ry, rz, w, h);

                    write!(writer, "`\n").unwrap();
                    output_html_frame(&mut writer, &fb);
                    if frame_idx < n_frames - 1 {
                        write!(writer, " `,\n").unwrap();
                    } else {
                        write!(writer, " `];\n").unwrap();
                    }
                }
            } else {
                // Static image mode
                let fb = render_model(&combined_model, rx, ry, rz, w, h);
                output_ansi(&mut writer, &fb);
            }
        }
        _ => {
            // Terminal mode (interactive-ish, but just output static frame)
            // We need to determine terminal size or use default
            // Based on the executable behavior, terminal mode renders to terminal
            // with dynamic rotation. Let's just render a static frame.

            // For terminal mode, we need screen size
            // Default or use terminal size
            let (tw, th) = get_terminal_size();
            let fb = render_model(&combined_model, rx, ry, rz, tw, th);
            output_terminal(&mut writer, &fb);
        }
    }

    writer.flush().unwrap();
}

fn get_terminal_size() -> (usize, usize) {
    // Try to get terminal size, default to 80x24
    // On Linux, we can use ioctl
    use std::mem;

    #[repr(C)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }

    let mut ws: Winsize = unsafe { mem::zeroed() };
    let ret = unsafe {
        libc_ioctl(1, 0x5413, &mut ws as *mut _ as *mut std::ffi::c_void)
    };

    if ret == 0 && ws.ws_col > 0 && ws.ws_row > 0 {
        (ws.ws_col as usize, ws.ws_row as usize)
    } else {
        (80, 24)
    }
}

