use std::collections::HashMap;
use std::fs;
use std::io::{self, Write, BufWriter};
use std::path::Path;
use std::f32::consts::PI;

// ============ OBJ/MTL Parser ============

#[derive(Debug, Clone)]
struct Material {
    name: String,
    kd: [f32; 3],
}

#[derive(Debug, Clone)]
struct Face {
    vertices: Vec<usize>,
    normals: Vec<usize>,
    material_idx: usize,
}

#[derive(Debug)]
struct Model {
    vertices: Vec<[f32; 3]>,
    normals: Vec<[f32; 3]>,
    faces: Vec<Face>,
    materials: Vec<Material>,
}

fn load_mtl(path: &str) -> Vec<Material> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => {
            eprintln!("Expected to have materials.: OpenFileFailed");
            std::process::exit(101);
        }
    };

    let mut materials = Vec::new();
    let mut current_name = String::new();
    let mut current_kd = [0.0f32; 3];
    let mut has_current = false;

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("newmtl ") {
            if has_current {
                materials.push(Material { name: current_name.clone(), kd: current_kd });
            }
            current_name = line[7..].trim().to_string();
            current_kd = [0.0, 0.0, 0.0];
            has_current = true;
        } else if line.starts_with("Kd ") {
            let parts: Vec<f32> = line[3..].split_whitespace()
                .filter_map(|x| x.parse().ok())
                .collect();
            if parts.len() >= 3 {
                current_kd = [parts[0], parts[1], parts[2]];
            }
        }
    }
    if has_current {
        materials.push(Material { name: current_name, kd: current_kd });
    }

    materials
}

fn load_obj(path: &str) -> Model {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Failed to read OBJ file '{}': {}", path, e);
            std::process::exit(1);
        }
    };

    let obj_dir = Path::new(path).parent().unwrap_or(Path::new("."));

    let mut vertices: Vec<[f32; 3]> = Vec::new();
    let mut normals: Vec<[f32; 3]> = Vec::new();
    let mut faces: Vec<Face> = Vec::new();
    let mut materials: Vec<Material> = Vec::new();
    let mut material_map: HashMap<String, usize> = HashMap::new();
    let mut current_material: usize = 0;

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("mtllib ") {
            let mtl_file = line[7..].trim();
            let mtl_path = obj_dir.join(mtl_file);
            let mtl_path_str = mtl_path.to_str().unwrap_or(mtl_file);
            let loaded = load_mtl(mtl_path_str);
            for mat in loaded {
                let idx = materials.len();
                material_map.insert(mat.name.clone(), idx);
                materials.push(mat);
            }
        } else if line.starts_with("v ") {
            let parts: Vec<f32> = line[2..].split_whitespace()
                .filter_map(|x| x.parse().ok())
                .collect();
            if parts.len() >= 3 {
                vertices.push([parts[0], parts[1], parts[2]]);
            }
        } else if line.starts_with("vn ") {
            let parts: Vec<f32> = line[3..].split_whitespace()
                .filter_map(|x| x.parse().ok())
                .collect();
            if parts.len() >= 3 {
                normals.push([parts[0], parts[1], parts[2]]);
            }
        } else if line.starts_with("usemtl ") {
            let mat_name = line[7..].trim();
            current_material = *material_map.get(mat_name).unwrap_or(&0);
        } else if line.starts_with("f ") {
            let tokens: Vec<&str> = line[2..].split_whitespace().collect();
            let mut verts = Vec::new();
            let mut norms = Vec::new();
            for token in &tokens {
                let parts: Vec<&str> = token.split('/').collect();
                if !parts[0].is_empty() {
                    if let Ok(v) = parts[0].parse::<i32>() {
                        let vi = if v < 0 {
                            (vertices.len() as i32 + v) as usize
                        } else {
                            (v - 1) as usize
                        };
                        verts.push(vi);
                    }
                }
                if parts.len() >= 3 && !parts[2].is_empty() {
                    if let Ok(n) = parts[2].parse::<i32>() {
                        let ni = if n < 0 {
                            (normals.len() as i32 + n) as usize
                        } else {
                            (n - 1) as usize
                        };
                        norms.push(ni);
                    }
                }
            }
            if verts.len() >= 3 {
                faces.push(Face {
                    vertices: verts,
                    normals: norms,
                    material_idx: current_material,
                });
            }
        }
    }

    Model { vertices, normals, faces, materials }
}

// ============ Math Utilities ============

fn cross(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    [
        a[1]*b[2] - a[2]*b[1],
        a[2]*b[0] - a[0]*b[2],
        a[0]*b[1] - a[1]*b[0],
    ]
}

fn sub3(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    [a[0]-b[0], a[1]-b[1], a[2]-b[2]]
}

fn dot3(a: [f32; 3], b: [f32; 3]) -> f32 {
    a[0]*b[0] + a[1]*b[1] + a[2]*b[2]
}

fn normalize3(a: [f32; 3]) -> [f32; 3] {
    let len = (a[0]*a[0] + a[1]*a[1] + a[2]*a[2]).sqrt();
    if len > 1e-10 { [a[0]/len, a[1]/len, a[2]/len] } else { a }
}

fn rotate_y(v: [f32; 3], theta: f32) -> [f32; 3] {
    let (s, c) = (theta.sin(), theta.cos());
    [v[0]*c + v[2]*s, v[1], -v[0]*s + v[2]*c]
}

fn rotate_x(v: [f32; 3], theta: f32) -> [f32; 3] {
    let (s, c) = (theta.sin(), theta.cos());
    [v[0], v[1]*c - v[2]*s, v[1]*s + v[2]*c]
}

fn rotate_z(v: [f32; 3], theta: f32) -> [f32; 3] {
    let (s, c) = (theta.sin(), theta.cos());
    [v[0]*c - v[1]*s, v[0]*s + v[1]*c, v[2]]
}

fn apply_rotation(v: [f32; 3], rx: f32, ry: f32, rz: f32) -> [f32; 3] {
    let v = rotate_x(v, rx);
    let v = rotate_y(v, ry);
    rotate_z(v, rz)
}

// ============ Rendering ============

const SHADE_CHARS: &[char] = &['.', ':', '-', '=', '+', '*', '#', '%'];

fn shade_char(dot_val: f32) -> char {
    if dot_val <= 0.0 {
        return ' ';
    }
    let idx = ((dot_val * 10.0) as i32 - 1).max(0).min(7) as usize;
    SHADE_CHARS[idx]
}

fn kd_to_rgb(kd: [f32; 3]) -> [u8; 3] {
    [(kd[0] * 255.0) as u8, (kd[1] * 255.0) as u8, (kd[2] * 255.0) as u8]
}

struct FrameBuffer {
    width: usize,
    height: usize,
    colors: Vec<Option<[u8; 3]>>,
    chars: Vec<char>,
    zbuf: Vec<f32>,
}

impl FrameBuffer {
    fn new(width: usize, height: usize) -> Self {
        let n = width * height;
        FrameBuffer {
            width,
            height,
            colors: vec![None; n],
            chars: vec![' '; n],
            zbuf: vec![f32::INFINITY; n],
        }
    }

    fn set_pixel(&mut self, x: i32, y: i32, z: f32, color: [u8; 3], ch: char) {
        if x < 0 || y < 0 || x >= self.width as i32 || y >= self.height as i32 {
            return;
        }
        let idx = y as usize * self.width + x as usize;
        if z < self.zbuf[idx] {
            self.zbuf[idx] = z;
            self.colors[idx] = Some(color);
            self.chars[idx] = ch;
        }
    }
}

fn compute_projection_params(model: &Model, rx: f32, ry: f32, rz: f32, width: usize, height: usize) 
    -> (f32, f32, f32, f32, f32) 
{
    if model.vertices.is_empty() {
        return (1.0, 0.0, 0.0, (width as f32)/2.0, (height as f32)/2.0);
    }

    let mut min_x = f32::INFINITY;
    let mut max_x = f32::NEG_INFINITY;
    let mut min_y = f32::INFINITY;
    let mut max_y = f32::NEG_INFINITY;

    for v in &model.vertices {
        let rv = apply_rotation(*v, rx, ry, rz);
        min_x = min_x.min(rv[0]);
        max_x = max_x.max(rv[0]);
        min_y = min_y.min(rv[1]);
        max_y = max_y.max(rv[1]);
    }

    let model_w = max_x - min_x;
    let model_h = max_y - min_y;

    let w = width as f32;
    let h = height as f32;

    let scale_from_w = if model_w > 1e-6 { (w - 1.0) / model_w } else { w };
    let scale_from_h = if model_h > 1e-6 { (h - 1.0) * 2.0 / model_h } else { h };
    let scale = scale_from_w.min(scale_from_h);

    let model_cx = (min_x + max_x) / 2.0;
    let model_cy = (min_y + max_y) / 2.0;
    let screen_cx = (w - 1.0) / 2.0;
    let screen_cy = (h - 1.0) / 2.0;

    (scale, model_cx, model_cy, screen_cx, screen_cy)
}

fn project_vertex(v: [f32; 3], scale: f32, model_cx: f32, model_cy: f32, screen_cx: f32, screen_cy: f32) 
    -> (f32, f32, f32) 
{
    let sx = (v[0] - model_cx) * scale + screen_cx;
    let sy = -(v[1] - model_cy) * (scale / 2.0) + screen_cy;
    (sx, sy, v[2])
}

fn rasterize_triangle(
    fb: &mut FrameBuffer,
    v0: (f32, f32, f32),
    v1: (f32, f32, f32),
    v2: (f32, f32, f32),
    color: [u8; 3], ch: char,
) {
    let (x0, y0, z0) = v0;
    let (x1, y1, z1) = v1;
    let (x2, y2, z2) = v2;

    let min_x = (x0.min(x1).min(x2).floor() as i32).max(0);
    let max_x = (x0.max(x1).max(x2).ceil() as i32).min(fb.width as i32 - 1);
    let min_y = (y0.min(y1).min(y2).floor() as i32).max(0);
    let max_y = (y0.max(y1).max(y2).ceil() as i32).min(fb.height as i32 - 1);

    let denom = (y1 - y2) * (x0 - x2) + (x2 - x1) * (y0 - y2);
    if denom.abs() < 1e-10 {
        return;
    }

    for py in min_y..=max_y {
        for px in min_x..=max_x {
            let px_f = px as f32 + 0.5;
            let py_f = py as f32 + 0.5;

            let w0 = ((y1 - y2) * (px_f - x2) + (x2 - x1) * (py_f - y2)) / denom;
            let w1 = ((y2 - y0) * (px_f - x2) + (x0 - x2) * (py_f - y2)) / denom;
            let w2 = 1.0 - w0 - w1;

            if w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0 {
                let z = w0 * z0 + w1 * z1 + w2 * z2;
                fb.set_pixel(px, py, z, color, ch);
            }
        }
    }
}

fn render_model(model: &Model, rx: f32, ry: f32, rz: f32, width: usize, height: usize) -> FrameBuffer {
    let mut fb = FrameBuffer::new(width, height);

    if model.vertices.is_empty() || model.faces.is_empty() {
        return fb;
    }

    let (scale, model_cx, model_cy, screen_cx, screen_cy) = 
        compute_projection_params(model, rx, ry, rz, width, height);

    let light = [0.0f32, 0.0, 1.0];

    for face in &model.faces {
        if face.vertices.len() < 3 { continue; }

        let n_mats = model.materials.len();
        if n_mats == 0 { continue; }
        let mat = &model.materials[face.material_idx.min(n_mats - 1)];
        let color = kd_to_rgb(mat.kd);

        // Get face normal
        let face_normal = if !face.normals.is_empty() {
            let ni = face.normals[0];
            if ni >= model.normals.len() { continue; }
            apply_rotation(model.normals[ni], rx, ry, rz)
        } else {
            let get_v = |i: usize| {
                let vi = face.vertices[i];
                if vi >= model.vertices.len() { return [0.0f32; 3]; }
                apply_rotation(model.vertices[vi], rx, ry, rz)
            };
            let v0 = get_v(0);
            let v1 = get_v(1);
            let v2 = get_v(2);
            normalize3(cross(sub3(v1, v0), sub3(v2, v0)))
        };

        let dot_nl = dot3(face_normal, light);
        if dot_nl <= 0.0 { continue; }

        let ch = shade_char(dot_nl);

        // Project vertices
        let proj_verts: Vec<(f32, f32, f32)> = face.vertices.iter()
            .filter_map(|&vi| {
                if vi >= model.vertices.len() { return None; }
                let rv = apply_rotation(model.vertices[vi], rx, ry, rz);
                Some(project_vertex(rv, scale, model_cx, model_cy, screen_cx, screen_cy))
            })
            .collect();

        if proj_verts.len() < 3 { continue; }

        for i in 1..proj_verts.len()-1 {
            rasterize_triangle(
                &mut fb,
                proj_verts[0], proj_verts[i], proj_verts[i+1],
                color, ch
            );
        }
    }

    fb
}

// ============ Output ============

fn output_ansi<W: Write>(writer: &mut W, fb: &FrameBuffer) {
    let w = fb.width;
    let h = fb.height;

    for y in 0..h {
        for x in 0..w {
            let idx = y * w + x;
            let (fg_r, fg_g, fg_b, ch) = match fb.colors[idx] {
                Some(c) => (c[0], c[1], c[2], fb.chars[idx]),
                None => (0u8, 0u8, 0u8, ' '),
            };
            const BG: u8 = 25;

            if x == w - 1 && y < h - 1 {
                write!(writer, "\x1b[48;2;{BG};{BG};{BG}m\x1b[38;2;{fg_r};{fg_g};{fg_b}m\n\x1b[49m\x1b[39m").unwrap();
            } else {
                write!(writer, "\x1b[48;2;{BG};{BG};{BG}m\x1b[38;2;{fg_r};{fg_g};{fg_b}m{ch}\x1b[49m\x1b[39m").unwrap();
            }
        }
    }
}

fn output_html_frame<W: Write>(writer: &mut W, fb: &FrameBuffer) {
    let w = fb.width;
    let h = fb.height;

    for y in 0..h {
        for x in 0..w {
            let idx = y * w + x;
            let (r, g, b, ch) = match fb.colors[idx] {
                Some(c) => (c[0], c[1], c[2], fb.chars[idx]),
                None => (0u8, 0u8, 0u8, ' '),
            };
            write!(writer, "<span style=\"color:rgb({r},{g},{b})\">{ch}").unwrap();
        }
        if y < h - 1 {
            write!(writer, "\n").unwrap();
        }
    }
}

// ============ Terminal Size ============

fn get_terminal_size() -> (usize, usize) {
    #[repr(C)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        _ws_xpixel: u16,
        _ws_ypixel: u16,
    }

    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }

    let mut ws = Winsize { ws_row: 0, ws_col: 0, _ws_xpixel: 0, _ws_ypixel: 0 };
    let ret = unsafe { ioctl(1, 0x5413u64, &mut ws as *mut Winsize) };

    if ret == 0 && ws.ws_col > 0 && ws.ws_row > 0 {
        (ws.ws_col as usize, ws.ws_row as usize)
    } else {
        (80, 24)
    }
}

// ============ Argument Parsing ============

fn parse_args(args: &[String]) -> (f32, f32, f32, Vec<String>, Option<String>, Option<usize>, Option<usize>, Option<usize>) {
    let mut rx = 0.0f32;
    let mut ry = 0.0f32;
    let mut rz = 0.0f32;
    let mut input_files: Vec<String> = Vec::new();
    let mut subcommand: Option<String> = None;
    let mut img_width: Option<usize> = None;
    let mut img_height: Option<usize> = None;
    let mut webify_frames: Option<usize> = None;

    let mut i = 0;
    let mut in_subcommand = false;

    while i < args.len() {
        let arg = &args[i];

        if in_subcommand {
            match arg.as_str() {
                "--help" => { print_image_help(); std::process::exit(0); }
                "-b" => {}
                "-w" => {
                    i += 1;
                    if i < args.len() { img_width = args[i].parse().ok(); }
                }
                "-h" => {
                    i += 1;
                    if i < args.len() { img_height = args[i].parse().ok(); }
                }
                "-j" | "--webify" => {
                    i += 1;
                    if i < args.len() { webify_frames = args[i].parse().ok(); }
                }
                "-x" | "--yaw" => {
                    i += 1;
                    if i < args.len() { if let Ok(v) = args[i].parse() { rx = v; } }
                }
                "-y" | "--pitch" => {
                    i += 1;
                    if i < args.len() { if let Ok(v) = args[i].parse() { ry = v; } }
                }
                "-z" | "--roll" => {
                    i += 1;
                    if i < args.len() { if let Ok(v) = args[i].parse() { rz = v; } }
                }
                _ => {}
            }
        } else {
            match arg.as_str() {
                "--help" | "-h" => { print_help(); std::process::exit(0); }
                "--version" | "-V" => { println!("Sloth 0.1"); std::process::exit(0); }
                "-b" => {}
                "-x" | "--yaw" => {
                    i += 1;
                    if i < args.len() { if let Ok(v) = args[i].parse() { rx = v; } }
                }
                "-y" | "--pitch" => {
                    i += 1;
                    if i < args.len() { if let Ok(v) = args[i].parse() { ry = v; } }
                }
                "-z" | "--roll" => {
                    i += 1;
                    if i < args.len() { if let Ok(v) = args[i].parse() { rz = v; } }
                }
                "image" if !input_files.is_empty() => {
                    subcommand = Some("image".to_string());
                    in_subcommand = true;
                }
                "help" => { print_help(); std::process::exit(0); }
                _ => { input_files.push(arg.clone()); }
            }
        }
        i += 1;
    }

    (rx, ry, rz, input_files, subcommand, img_width, img_height, webify_frames)
}

// ============ Main ============

fn main() {
    let argv: Vec<String> = std::env::args().skip(1).collect();

    if argv.is_empty() {
        print_help();
        return;
    }

    // Check for help/version first
    for arg in &argv {
        match arg.as_str() {
            "--help" | "-h" => { print_help(); return; }
            "--version" | "-V" => { println!("Sloth 0.1"); return; }
            _ => {}
        }
    }

    let (rx, ry, rz, input_files, subcommand, img_width, img_height, webify_frames) = parse_args(&argv);

    if input_files.is_empty() {
        print_help();
        return;
    }

    // Load model(s)
    let mut combined_model = Model {
        vertices: Vec::new(),
        normals: Vec::new(),
        faces: Vec::new(),
        materials: Vec::new(),
    };

    for filepath in &input_files {
        for path in filepath.split_whitespace() {
            if path.is_empty() { continue; }
            let model = load_obj(path);
            let vert_offset = combined_model.vertices.len();
            let norm_offset = combined_model.normals.len();
            let mat_offset = combined_model.materials.len();

            combined_model.vertices.extend(model.vertices);
            combined_model.normals.extend(model.normals);
            combined_model.materials.extend(model.materials);
            for mut f in model.faces {
                for v in &mut f.vertices { *v += vert_offset; }
                for n in &mut f.normals { *n += norm_offset; }
                f.material_idx += mat_offset;
                combined_model.faces.push(f);
            }
        }
    }

    let stdout = io::stdout();
    let mut writer = BufWriter::new(stdout.lock());

    match subcommand.as_deref() {
        Some("image") => {
            let w = match img_width {
                Some(w) => w,
                None => {
                    eprintln!("error: The following required arguments were not provided:\n    -w <width>\n\nFor more information try --help");
                    std::process::exit(1);
                }
            };
            let h = img_height.unwrap_or(w);

            if let Some(n_frames) = webify_frames {
                write!(writer, "let frames = [\n").unwrap();
                for frame_idx in 0..n_frames {
                    let theta = 2.0 * PI * frame_idx as f32 / n_frames as f32;
                    let frame_ry = ry + theta;

                    let fb = render_model(&combined_model, rx, frame_ry, rz, w, h);

                    write!(writer, "`\n").unwrap();
                    output_html_frame(&mut writer, &fb);
                    if frame_idx < n_frames - 1 {
                        write!(writer, " `,\n").unwrap();
                    } else {
                        write!(writer, " `];\n").unwrap();
                    }
                }
            } else {
                let fb = render_model(&combined_model, rx, ry, rz, w, h);
                output_ansi(&mut writer, &fb);
            }
        }
        _ => {
            let (tw, th) = get_terminal_size();
            let fb = render_model(&combined_model, rx, ry, rz, tw, th);
            output_ansi(&mut writer, &fb);
        }
    }

    writer.flush().unwrap();
}

fn print_help() {
    eprintln!("Sloth 0.1");
    eprintln!("Mitchell Hynes. <mshynes@mun.ca>");
    eprintln!("A toy for rendering 3D objects in the command line");
