use std::f32::consts::PI;

// ============ OBJ/MTL Parser ============

#[derive(Debug, Clone)]
struct Material {
    name: String,
    kd: [f32; 3],
}

#[derive(Debug, Clone)]
struct Face {
    vertices: Vec<usize>,
    normals: Vec<usize>,
    material_idx: usize,
}

#[derive(Debug)]
struct Model {
    vertices: Vec<[f32; 3]>,
    normals: Vec<[f32; 3]>,
    faces: Vec<Face>,
    materials: Vec<Material>,
