fn load_mtl(path: &str) -> Vec<Material> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => {
            eprintln!("Expected to have materials.: OpenFileFailed");
            std::process::exit(101);
        }
    };

    let mut materials = Vec::new();
    let mut current_name = String::new();
    let mut current_kd = [0.0f32; 3];
    let mut has_current = false;

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("newmtl ") {
            if has_current {
                materials.push(Material { name: current_name.clone(), kd: current_kd });
            }
            current_name = line[7..].trim().to_string();
            current_kd = [0.0, 0.0, 0.0];
            has_current = true;
        } else if line.starts_with("Kd ") {
            let parts: Vec<f32> = line[3..].split_whitespace()
                .filter_map(|x| x.parse().ok())
                .collect();
            if parts.len() >= 3 {
                current_kd = [parts[0], parts[1], parts[2]];
            }
        }
    }
    if has_current {
        materials.push(Material { name: current_name, kd: current_kd });
    }

    materials
}

fn load_obj(path: &str) -> Model {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Failed to read OBJ file '{}': {}", path, e);
            std::process::exit(1);
        }
    };

    let obj_dir = Path::new(path).parent().unwrap_or(Path::new("."));

    let mut vertices: Vec<[f32; 3]> = Vec::new();
    let mut normals: Vec<[f32; 3]> = Vec::new();
    let mut faces: Vec<Face> = Vec::new();
    let mut materials: Vec<Material> = Vec::new();
    let mut material_map: HashMap<String, usize> = HashMap::new();
    let mut current_material: usize = 0;

    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("mtllib ") {
            let mtl_file = line[7..].trim();
            let mtl_path = obj_dir.join(mtl_file);
            let mtl_path_str = mtl_path.to_str().unwrap_or(mtl_file);
            let loaded = load_mtl(mtl_path_str);
            for mat in loaded {
                let idx = materials.len();
                material_map.insert(mat.name.clone(), idx);
                materials.push(mat);
            }
        } else if line.starts_with("v ") {
            let parts: Vec<f32> = line[2..].split_whitespace()
                .filter_map(|x| x.parse().ok())
                .collect();
            if parts.len() >= 3 {
                vertices.push([parts[0], parts[1], parts[2]]);
            }
        } else if line.starts_with("vn ") {
            let parts: Vec<f32> = line[3..].split_whitespace()
                .filter_map(|x| x.parse().ok())
                .collect();
            if parts.len() >= 3 {
                normals.push([parts[0], parts[1], parts[2]]);
            }
        } else if line.starts_with("usemtl ") {
            let mat_name = line[7..].trim();
            current_material = *material_map.get(mat_name).unwrap_or(&0);
        } else if line.starts_with("f ") {
            let tokens: Vec<&str> = line[2..].split_whitespace().collect();
            let mut verts = Vec::new();
            let mut norms = Vec::new();
            for token in &tokens {
                let parts: Vec<&str> = token.split('/').collect();
                if !parts[0].is_empty() {
                    if let Ok(v) = parts[0].parse::<i32>() {
                        let vi = if v < 0 { (vertices.len() as i32 + v) as usize } else { (v - 1) as usize };
                        verts.push(vi);
                    }
                }
                if parts.len() >= 3 && !parts[2].is_empty() {
                    if let Ok(n) = parts[2].parse::<i32>() {
                        let ni = if n < 0 { (normals.len() as i32 + n) as usize } else { (n - 1) as usize };
                        norms.push(ni);
                    }
                }
            }
            if verts.len() >= 3 {
                faces.push(Face { vertices: verts, normals: norms, material_idx: current_material });
            }
        }
    }

    Model { vertices, normals, faces, materials }
}

// ============ Math ============

fn cross(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]
}
fn sub3(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    [a[0]-b[0], a[1]-b[1], a[2]-b[2]]
}
fn dot3(a: [f32; 3], b: [f32; 3]) -> f32 {
    a[0]*b[0]+a[1]*b[1]+a[2]*b[2]
}
fn normalize3(a: [f32; 3]) -> [f32; 3] {
    let len = (a[0]*a[0]+a[1]*a[1]+a[2]*a[2]).sqrt();
    if len > 1e-10 { [a[0]/len, a[1]/len, a[2]/len] } else { a }
}
fn rotate_y(v: [f32; 3], theta: f32) -> [f32; 3] {
    let (s, c) = (theta.sin(), theta.cos());
    [v[0]*c+v[2]*s, v[1], -v[0]*s+v[2]*c]
}
fn rotate_x(v: [f32; 3], theta: f32) -> [f32; 3] {
    let (s, c) = (theta.sin(), theta.cos());
    [v[0], v[1]*c-v[2]*s, v[1]*s+v[2]*c]
}
fn rotate_z(v: [f32; 3], theta: f32) -> [f32; 3] {
    let (s, c) = (theta.sin(), theta.cos());
    [v[0]*c-v[1]*s, v[0]*s+v[1]*c, v[2]]
}
fn apply_rotation(v: [f32; 3], rx: f32, ry: f32, rz: f32) -> [f32; 3] {
    rotate_z(rotate_y(rotate_x(v, rx), ry), rz)
}

// ============ Rendering ============

const SHADE_CHARS: &[u8] = b".:-=-+*#%";
// index 0 = '.' (faintest), index 7 = '%' (brightest), index 8 = '%' (clamped)
// Actually: '.', ':', '-', '=', '+', '*', '#', '%'

fn shade_char(dot_val: f32) -> u8 {
    if dot_val <= 0.0 { return b' '; }
    // chars: '.', ':', '-', '=', '+', '*', '#', '%' (8 chars, index 0..7)
    let chars: &[u8] = b".:-=-+*#%";
    let idx = ((dot_val * 10.0) as i32 - 1).max(0).min(7) as usize;
    b".:-=-+*#%"[idx];
    // Use the correct array:
    let shades: [u8; 8] = [b'.', b':', b'-', b'=', b'+', b'*', b'#', b'%'];
    shades[idx]
}

fn kd_to_rgb(kd: [f32; 3]) -> [u8; 3] {
    [(kd[0]*255.0) as u8, (kd[1]*255.0) as u8, (kd[2]*255.0) as u8]
}

// The image buffer: (w+1) x h pixels
// Each pixel: [fg_r, fg_g, fg_b, char_byte]
// char = ' ' for background, '\n' for newline, or shading char for model
// fg color = (0,0,0) for background/newline, material color for model

struct ImageBuffer {
    width: usize,   // w+1
    height: usize,  // h
    fg: Vec<[u8; 3]>,
    ch: Vec<u8>,
    zbuf: Vec<f32>,
    visited_rows: std::collections::BTreeSet<usize>, // rows visited by rasterizer
}

impl ImageBuffer {
    fn new(w: usize, h: usize) -> Self {
        let width = w + 1;
        let n = width * h;
        ImageBuffer {
            width,
            height: h,
            fg: vec![[0u8; 3]; n],
            ch: vec![b' '; n],
            zbuf: vec![f32::INFINITY; n],
            visited_rows: std::collections::BTreeSet::new(),
        }
    }

    fn set_pixel(&mut self, x: i32, y: i32, z: f32, color: [u8; 3], ch: u8) {
        if x < 0 || y < 0 || x >= self.width as i32 || y >= self.height as i32 {
            return;
        }
        let idx = y as usize * self.width + x as usize;
        if z < self.zbuf[idx] {
            self.zbuf[idx] = z;
            self.fg[idx] = color;
            self.ch[idx] = ch;
        }
    }

    fn mark_row_visited(&mut self, y: i32) {
        if y >= 0 && y < self.height as i32 {
            self.visited_rows.insert(y as usize);
        }
    }
}

fn get_projection_params(model: &Model, rx: f32, ry: f32, rz: f32, w: usize, h: usize) 
    -> (f32, f32, f32) 
{
    if model.vertices.is_empty() {
        return (1.0, (w as f32)/2.0, (h as f32 - 1.0)/2.0);
    }

    let mut min_x = f32::INFINITY;
    let mut max_x = f32::NEG_INFINITY;
    let mut min_y = f32::INFINITY;
    let mut max_y = f32::NEG_INFINITY;

    for v in &model.vertices {
        let rv = apply_rotation(*v, rx, ry, rz);
        if rv[0] < min_x { min_x = rv[0]; }
        if rv[0] > max_x { max_x = rv[0]; }
        if rv[1] < min_y { min_y = rv[1]; }
        if rv[1] > max_y { max_y = rv[1]; }
    }

    let model_w = max_x - min_x;
    let model_h = max_y - min_y;

    // scale_x: image columns per 3D unit, centered in image
    let scale_x = if model_w > 1e-6 { w as f32 / model_w } else { 1.0 };
    // scale_y: image rows per 3D unit = scale_x / 2 (2:1 terminal aspect ratio)
    let scale_from_h = if model_h > 1e-6 { (h as f32 - 1.0) * 2.0 / model_h } else { 1.0 };
    let scale = scale_x.min(scale_from_h);

    let screen_cx = (w as f32) / 2.0;
    let screen_cy = (h as f32 - 1.0) / 2.0;

    // We ignore model center; just use scale
    (scale, screen_cx, screen_cy)
}

fn project_vertex_xy(v: [f32; 3], scale: f32, screen_cx: f32, screen_cy: f32) -> (f32, f32, f32) {
    let sx = v[0] * scale + screen_cx;
    let sy = -v[1] * (scale / 2.0) + screen_cy;  // y flipped, /2 for 2:1 aspect
    (sx, sy, v[2])
}

fn rasterize_triangle(
    fb: &mut ImageBuffer,
    v0: (f32, f32, f32),
    v1: (f32, f32, f32),
    v2: (f32, f32, f32),
    color: [u8; 3], ch: u8,
) {
    let (x0, y0, z0) = v0;
    let (x1, y1, z1) = v1;
    let (x2, y2, z2) = v2;

    let min_x = (x0.min(x1).min(x2).floor() as i32).max(0);
    let max_x = (x0.max(x1).max(x2).ceil() as i32).min(fb.width as i32 - 1);
    let min_y = (y0.min(y1).min(y2).floor() as i32).max(0);
    let max_y = (y0.max(y1).max(y2).ceil() as i32).min(fb.height as i32 - 1);

    // Mark all rows in bounding box as visited
    for py in min_y..=max_y {
        fb.mark_row_visited(py);
    }

    let denom = (y1 - y2) * (x0 - x2) + (x2 - x1) * (y0 - y2);
    if denom.abs() < 1e-10 { return; }

    for py in min_y..=max_y {
        for px in min_x..=max_x {
            let px_f = px as f32 + 0.5;
            let py_f = py as f32 + 0.5;

            let w0 = ((y1-y2)*(px_f-x2) + (x2-x1)*(py_f-y2)) / denom;
            let w1 = ((y2-y0)*(px_f-x2) + (x0-x2)*(py_f-y2)) / denom;
            let w2 = 1.0 - w0 - w1;

            if w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0 {
                let z = w0*z0 + w1*z1 + w2*z2;
                fb.set_pixel(px, py, z, color, ch);
            }
        }
    }
}

fn render_model(model: &Model, rx: f32, ry: f32, rz: f32, w: usize, h: usize) -> ImageBuffer {
    let mut fb = ImageBuffer::new(w, h);

    if model.vertices.is_empty() || model.faces.is_empty() || model.materials.is_empty() {
        return fb;
    }

    let (scale, screen_cx, screen_cy) = get_projection_params(model, rx, ry, rz, w, h);

    let light = [0.0f32, 0.0, 1.0];

    for face in &model.faces {
        if face.vertices.len() < 3 { continue; }

        let mat = &model.materials[face.material_idx.min(model.materials.len()-1)];
        let color = kd_to_rgb(mat.kd);

        // Face normal
        let face_normal = if !face.normals.is_empty() {
            let ni = face.normals[0];
            if ni >= model.normals.len() { continue; }
            apply_rotation(model.normals[ni], rx, ry, rz)
        } else {
            let get_v = |i: usize| -> [f32; 3] {
                let vi = face.vertices[i];
                if vi >= model.vertices.len() { return [0.0; 3]; }
                apply_rotation(model.vertices[vi], rx, ry, rz)
            };
            normalize3(cross(sub3(get_v(1), get_v(0)), sub3(get_v(2), get_v(0))))
        };

        let dot_nl = dot3(face_normal, light);
        if dot_nl <= 0.0 { continue; }

        let ch = shade_char(dot_nl);

        // Project vertices
        let proj: Vec<(f32, f32, f32)> = face.vertices.iter()
            .filter_map(|&vi| {
                if vi >= model.vertices.len() { return None; }
                let rv = apply_rotation(model.vertices[vi], rx, ry, rz);
                Some(project_vertex_xy(rv, scale, screen_cx, screen_cy))
            })
            .collect();

        if proj.len() < 3 { continue; }

        // Fan triangulation
        for i in 1..proj.len()-1 {
            rasterize_triangle(&mut fb, proj[0], proj[i], proj[i+1], color, ch);
        }
    }

    // Place newlines at visited rows
    // Formula: at image row y (y >= 1), nl_col = (1 - y as i32).rem_euclid(w as i32) as usize
    for &y in &fb.visited_rows {
        if y == 0 { continue; }
        let w_i = w as i32;
        let nl_col = (1 - y as i32).rem_euclid(w_i) as usize;
        let idx = y * fb.width + nl_col;
        // Only place newline if it's a background pixel (don't overwrite model content)
        if fb.ch[idx] == b' ' || fb.ch[idx] == b'\n' {
            fb.ch[idx] = b'\n';
            fb.fg[idx] = [0u8; 3];
        }
    }

    fb
}

// ============ Output ============

fn output_ansi<W: Write>(writer: &mut W, fb: &ImageBuffer) {
    for y in 0..fb.height {
        for x in 0..fb.width {
            let idx = y * fb.width + x;
            let fg = fb.fg[idx];
            let ch = fb.ch[idx];
            const BG: u8 = 25;
            write!(writer, "\x1b[48;2;{BG};{BG};{BG}m\x1b[38;2;{};{};{}m{}\x1b[49m\x1b[39m",
                fg[0], fg[1], fg[2], ch as char).unwrap();
        }
    }
}

fn output_html_frame<W: Write>(writer: &mut W, fb: &ImageBuffer) {
    let mut first = true;
    let mut cur_row_count = 0;

    // We need to output the terminal rows (split by '\n' pixels)
    // Each terminal row = sequence of pixels until a '\n' pixel (exclusive)
    // Then the '\n' pixel ends that row (and in HTML it becomes a newline)

    for y in 0..fb.height {
        for x in 0..fb.width {
            let idx = y * fb.width + x;
            let fg = fb.fg[idx];
            let ch = fb.ch[idx];

            if ch == b'\n' {
                // This '\n' pixel terminates the current HTML line
                write!(writer, "\n").unwrap();
                cur_row_count += 1;
            } else {
                write!(writer, "<span style=\"color:rgb({},{},{})\">{}",
                    fg[0], fg[1], fg[2], ch as char).unwrap();
            }
        }
    }
}

// ============ Terminal Size ============

fn get_terminal_size() -> (usize, usize) {
    #[repr(C)]
    struct Winsize { ws_row: u16, ws_col: u16, _p: u32 }
    extern "C" { fn ioctl(fd: i32, request: u64, ...) -> i32; }
    let mut ws = Winsize { ws_row: 0, ws_col: 0, _p: 0 };
    let ret = unsafe { ioctl(1, 0x5413u64, &mut ws as *mut Winsize) };
    if ret == 0 && ws.ws_col > 0 && ws.ws_row > 0 {
        (ws.ws_col as usize, ws.ws_row as usize)
    } else {
        (80, 24)
    }
}

// ============ Arg Parsing ============

fn parse_args(args: &[String]) -> (f32, f32, f32, Vec<String>, Option<String>, Option<usize>, Option<usize>, Option<usize>) {
    let mut rx = 0.0f32; let mut ry = 0.0f32; let mut rz = 0.0f32;
    let mut input_files: Vec<String> = Vec::new();
    let mut subcommand: Option<String> = None;
    let mut img_width: Option<usize> = None;
    let mut img_height: Option<usize> = None;
    let mut webify_frames: Option<usize> = None;
    let mut i = 0;
    let mut in_sub = false;

    while i < args.len() {
        let arg = &args[i];
        if in_sub {
            match arg.as_str() {
                "--help" => { print_image_help(); std::process::exit(0); }
                "-b" => {}
                "-w" => { i += 1; if i < args.len() { img_width = args[i].parse().ok(); } }
                "-h" => { i += 1; if i < args.len() { img_height = args[i].parse().ok(); } }
                "-j" | "--webify" => { i += 1; if i < args.len() { webify_frames = args[i].parse().ok(); } }
                "-x" | "--yaw" => { i += 1; if i < args.len() { if let Ok(v) = args[i].parse() { rx = v; } } }
                "-y" | "--pitch" => { i += 1; if i < args.len() { if let Ok(v) = args[i].parse() { ry = v; } } }
                "-z" | "--roll" => { i += 1; if i < args.len() { if let Ok(v) = args[i].parse() { rz = v; } } }
                _ => {}
            }
        } else {
            match arg.as_str() {
                "--help" | "-h" => { print_help(); std::process::exit(0); }
                "--version" | "-V" => { println!("Sloth 0.1"); std::process::exit(0); }
                "-b" => {}
                "-x" | "--yaw" => { i += 1; if i < args.len() { if let Ok(v) = args[i].parse() { rx = v; } } }
                "-y" | "--pitch" => { i += 1; if i < args.len() { if let Ok(v) = args[i].parse() { ry = v; } } }
                "-z" | "--roll" => { i += 1; if i < args.len() { if let Ok(v) = args[i].parse() { rz = v; } } }
                "image" if !input_files.is_empty() => { subcommand = Some("image".to_string()); in_sub = true; }
                "help" => { print_help(); std::process::exit(0); }
                _ => { input_files.push(arg.clone()); }
            }
        }
        i += 1;
    }

    (rx, ry, rz, input_files, subcommand, img_width, img_height, webify_frames)
}

// ============ Main ============

fn main() {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    if argv.is_empty() { print_help(); return; }

    let (rx, ry, rz, input_files, subcommand, img_width, img_height, webify_frames) = parse_args(&argv);

    if input_files.is_empty() { print_help(); return; }

    // Load models
    let mut combined = Model { vertices: vec![], normals: vec![], faces: vec![], materials: vec![] };

    for filepath in &input_files {
        for path in filepath.split_whitespace() {
            if path.is_empty() { continue; }
            let model = load_obj(path);
            let vo = combined.vertices.len();
            let no = combined.normals.len();
            let mo = combined.materials.len();
            combined.vertices.extend(model.vertices);
            combined.normals.extend(model.normals);
            combined.materials.extend(model.materials);
            for mut f in model.faces {
                for v in &mut f.vertices { *v += vo; }
                for n in &mut f.normals { *n += no; }
                f.material_idx += mo;
                combined.faces.push(f);
            }
        }
    }

    let stdout = io::stdout();
    let mut writer = BufWriter::new(stdout.lock());

    match subcommand.as_deref() {
        Some("image") => {
            let w = img_width.unwrap_or_else(|| {
                eprintln!("error: The following required arguments were not provided:\n    -w <width>\n\nFor more information try --help");
                std::process::exit(1);
            });
            let h = img_height.unwrap_or(w);

            if let Some(n_frames) = webify_frames {
                write!(writer, "let frames = [\n").unwrap();
                for fi in 0..n_frames {
                    let theta = 2.0 * PI * fi as f32 / n_frames as f32;
                    let fb = render_model(&combined, rx, ry + theta, rz, w, h);
                    write!(writer, "`\n").unwrap();
                    output_html_frame(&mut writer, &fb);
                    if fi < n_frames - 1 {
                        write!(writer, " `,\n").unwrap();
                    } else {
                        write!(writer, " `];\n").unwrap();
                    }
                }
            } else {
                let fb = render_model(&combined, rx, ry, rz, w, h);
                output_ansi(&mut writer, &fb);
            }
        }
        _ => {
            let (tw, th) = get_terminal_size();
            let fb = render_model(&combined, rx, ry, rz, tw, th);
            output_ansi(&mut writer, &fb);
        }
    }

    writer.flush().unwrap();
}

fn print_help() {
