use std::collections::HashMap;
use std::fs;
use std::io::{self, Write, BufWriter};
use std::path::Path;
use std::f32::consts::PI;

#[derive(Debug, Clone)]
struct Material { name: String, kd: [f32; 3] }

#[derive(Debug, Clone)]
struct Face { vertices: Vec<usize>, normals: Vec<usize>, material_idx: usize }

#[derive(Debug)]
struct Model {
    vertices: Vec<[f32; 3]>,
    normals: Vec<[f32; 3]>,
    faces: Vec<Face>,
    materials: Vec<Material>,
}

fn load_mtl(path: &str) -> Vec<Material> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => { eprintln!("Expected to have materials.: OpenFileFailed"); std::process::exit(101); }
    };
    let mut mats = Vec::new();
    let mut cname = String::new();
    let mut ckd = [0.0f32; 3];
    let mut has = false;
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("newmtl ") {
            if has { mats.push(Material { name: cname.clone(), kd: ckd }); }
            cname = line[7..].trim().to_string(); ckd = [0.0; 3]; has = true;
        } else if line.starts_with("Kd ") {
            let p: Vec<f32> = line[3..].split_whitespace().filter_map(|x| x.parse().ok()).collect();
            if p.len() >= 3 { ckd = [p[0], p[1], p[2]]; }
        }
    }
    if has { mats.push(Material { name: cname, kd: ckd }); }
    mats
}

fn load_obj(path: &str) -> Model {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => { eprintln!("Failed to read OBJ file '{}': {}", path, e); std::process::exit(1); }
    };
    let obj_dir = Path::new(path).parent().unwrap_or(Path::new("."));
    let mut verts: Vec<[f32; 3]> = vec![];
    let mut norms: Vec<[f32; 3]> = vec![];
    let mut faces: Vec<Face> = vec![];
    let mut mats: Vec<Material> = vec![];
    let mut mmap: HashMap<String, usize> = HashMap::new();
    let mut cur_mat = 0usize;
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("mtllib ") {
            let mp = obj_dir.join(line[7..].trim());
            let loaded = load_mtl(mp.to_str().unwrap_or(""));
            for mat in loaded { let i = mats.len(); mmap.insert(mat.name.clone(), i); mats.push(mat); }
        } else if line.starts_with("v ") {
            let p: Vec<f32> = line[2..].split_whitespace().filter_map(|x| x.parse().ok()).collect();
            if p.len() >= 3 { verts.push([p[0], p[1], p[2]]); }
        } else if line.starts_with("vn ") {
            let p: Vec<f32> = line[3..].split_whitespace().filter_map(|x| x.parse().ok()).collect();
            if p.len() >= 3 { norms.push([p[0], p[1], p[2]]); }
        } else if line.starts_with("usemtl ") {
            cur_mat = *mmap.get(line[7..].trim()).unwrap_or(&0);
        } else if line.starts_with("f ") {
            let tokens: Vec<&str> = line[2..].split_whitespace().collect();
            let mut fverts = vec![];
            let mut fnorms = vec![];
            for tok in &tokens {
                let parts: Vec<&str> = tok.split('/').collect();
                if !parts[0].is_empty() {
                    if let Ok(v) = parts[0].parse::<i32>() {
                        fverts.push(if v < 0 { (verts.len() as i32 + v) as usize } else { (v-1) as usize });
                    }
                }
                if parts.len() >= 3 && !parts[2].is_empty() {
                    if let Ok(n) = parts[2].parse::<i32>() {
                        fnorms.push(if n < 0 { (norms.len() as i32 + n) as usize } else { (n-1) as usize });
                    }
                }
            }
            if fverts.len() >= 3 { faces.push(Face { vertices: fverts, normals: fnorms, material_idx: cur_mat }); }
        }
    }
    Model { vertices: verts, normals: norms, faces, materials: mats }
}

fn cross(a:[f32;3], b:[f32;3]) -> [f32;3] { [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]] }
fn sub3(a:[f32;3], b:[f32;3]) -> [f32;3] { [a[0]-b[0], a[1]-b[1], a[2]-b[2]] }
fn dot3(a:[f32;3], b:[f32;3]) -> f32 { a[0]*b[0]+a[1]*b[1]+a[2]*b[2] }
fn normalize3(a:[f32;3]) -> [f32;3] {
    let l = (a[0]*a[0]+a[1]*a[1]+a[2]*a[2]).sqrt();
    if l > 1e-10 { [a[0]/l, a[1]/l, a[2]/l] } else { a }
}
fn ry(v:[f32;3], t:f32) -> [f32;3] { let (s,c)=(t.sin(),t.cos()); [v[0]*c+v[2]*s, v[1], -v[0]*s+v[2]*c] }
fn rx(v:[f32;3], t:f32) -> [f32;3] { let (s,c)=(t.sin(),t.cos()); [v[0], v[1]*c-v[2]*s, v[1]*s+v[2]*c] }
fn rz(v:[f32;3], t:f32) -> [f32;3] { let (s,c)=(t.sin(),t.cos()); [v[0]*c-v[1]*s, v[0]*s+v[1]*c, v[2]] }
fn apply_rot(v:[f32;3], rx_:f32, ry_:f32, rz_:f32) -> [f32;3] { rz(ry(rx(v,rx_),ry_),rz_) }

fn shade_char(d: f32) -> u8 {
    if d <= 0.0 { return b' '; }
    [b'.', b':', b'-', b'=', b'+', b'*', b'#', b'%'][((d*10.0) as i32-1).max(0).min(7) as usize]
}
fn kd_rgb(kd:[f32;3]) -> [u8;3] { [(kd[0]*255.0) as u8, (kd[1]*255.0) as u8, (kd[2]*255.0) as u8] }

struct Buf {
    w: usize, h: usize,
    fg: Vec<[u8;3]>, ch: Vec<u8>, zb: Vec<f32>,
    visited: std::collections::BTreeSet<usize>,
}
impl Buf {
    fn new(w:usize, h:usize) -> Self {
        let n=(w+1)*h;
        Buf { w, h, fg:vec![[0;3];n], ch:vec![b' ';n], zb:vec![f32::INFINITY;n], visited:Default::default() }
    }
    fn set(&mut self, x:i32, y:i32, z:f32, c:[u8;3], ch:u8) {
        if x<0||y<0||x>self.w as i32||y>=self.h as i32 { return; }
        let idx=y as usize*(self.w+1)+x as usize;
        if z<self.zb[idx] { self.zb[idx]=z; self.fg[idx]=c; self.ch[idx]=ch; }
    }
    fn visit(&mut self, y:i32) { if y>=0&&y<self.h as i32 { self.visited.insert(y as usize); } }
    fn finalize(&mut self) {
        let w=self.w;
        for &y in &self.visited {
            if y==0 { continue; }
            for x in 0..=w {
                if (x+y)%w==1 {
                    let idx=y*(w+1)+x;
                    self.ch[idx]=b'\n';
                    self.fg[idx]=[0;3];
                }
            }
        }
    }
}

fn render(model:&Model, rx_:f32, ry_:f32, rz_:f32, w:usize, h:usize) -> Buf {
    let mut fb=Buf::new(w,h);
    if model.vertices.is_empty()||model.faces.is_empty()||model.materials.is_empty() {
        fb.finalize(); return fb;
    }

    // Compute bounding box
    let (mut min_x,mut max_x,mut min_y,mut max_y) = (f32::INFINITY,f32::NEG_INFINITY,f32::INFINITY,f32::NEG_INFINITY);
    for v in &model.vertices {
        let rv=apply_rot(*v,rx_,ry_,rz_);
        if rv[0]<min_x{min_x=rv[0];} if rv[0]>max_x{max_x=rv[0];}
        if rv[1]<min_y{min_y=rv[1];} if rv[1]>max_y{max_y=rv[1];}
    }
    let mspan_x=max_x-min_x; let mspan_y=max_y-min_y;
    let mx=(min_x+max_x)/2.0; let my=(min_y+max_y)/2.0;

    // Scale
    let scale_x = if mspan_x>1e-6 { w as f32/mspan_x } else { 1.0 };
    // scale_y based on formula: v = w/2-3+h%2, scale_y = v/model_y_span
    let v = (w/2) as i32 - 3 + (h%2) as i32;
    let scale_y = if mspan_y>1e-6 { (v.max(1) as f32)/mspan_y } else { 1.0 };

    let scx=w as f32/2.0;
    let scy=(h as f32-1.0)/2.0;

    let light=[0.0f32,0.0,1.0];

    for face in &model.faces {
        if face.vertices.len()<3 { continue; }
        let mat=&model.materials[face.material_idx.min(model.materials.len()-1)];
        let color=kd_rgb(mat.kd);
        let fn_=if !face.normals.is_empty() {
            let ni=face.normals[0];
            if ni>=model.normals.len() { continue; }
            apply_rot(model.normals[ni],rx_,ry_,rz_)
        } else {
            let gv=|i:usize|->[f32;3]{
                let vi=face.vertices[i];
                if vi>=model.vertices.len(){return [0.0;3];}
                apply_rot(model.vertices[vi],rx_,ry_,rz_)
            };
            normalize3(cross(sub3(gv(1),gv(0)),sub3(gv(2),gv(0))))
        };
        let d=dot3(fn_,light);
        if d<=0.0 { continue; }
        let ch=shade_char(d);
        let proj:Vec<(f32,f32,f32)>=face.vertices.iter().filter_map(|&vi|{
            if vi>=model.vertices.len(){return None;}
            let rv=apply_rot(model.vertices[vi],rx_,ry_,rz_);
            let sx=(rv[0]-mx)*scale_x+scx;
            let sy=-(rv[1]-my)*scale_y+scy;
            Some((sx,sy,rv[2]))
        }).collect();
        if proj.len()<3 { continue; }
        for i in 1..proj.len()-1 {
            rasterize(&mut fb,proj[0],proj[i],proj[i+1],color,ch);
        }
    }
    fb.finalize();
    fb
}

fn rasterize(fb:&mut Buf, v0:(f32,f32,f32), v1:(f32,f32,f32), v2:(f32,f32,f32), color:[u8;3], ch:u8) {
    let (x0,y0,z0)=v0; let (x1,y1,z1)=v1; let (x2,y2,z2)=v2;
    let min_x=(x0.min(x1).min(x2).floor() as i32).max(0);
    let max_x=(x0.max(x1).max(x2).ceil() as i32).min(fb.w as i32);
    let min_y=(y0.min(y1).min(y2).floor() as i32).max(0);
    let max_y=(y0.max(y1).max(y2).ceil() as i32).min(fb.h as i32-1);
    for py in min_y..=max_y { fb.visit(py); }
    let denom=(y1-y2)*(x0-x2)+(x2-x1)*(y0-y2);
    if denom.abs()<1e-10 { return; }
    for py in min_y..=max_y {
        for px in min_x..=max_x {
            let pxf=px as f32+0.5; let pyf=py as f32+0.5;
            let w0=((y1-y2)*(pxf-x2)+(x2-x1)*(pyf-y2))/denom;
            let w1=((y2-y0)*(pxf-x2)+(x0-x2)*(pyf-y2))/denom;
            let w2=1.0-w0-w1;
            if w0>=0.0&&w1>=0.0&&w2>=0.0 {
                let z=w0*z0+w1*z1+w2*z2;
                fb.set(px,py,z,color,ch);
            }
        }
    }
}

fn output_ansi<W:Write>(w:&mut W, fb:&Buf) {
    const BG:u8=25;
    for y in 0..fb.h {
        for x in 0..=fb.w {
            let idx=y*(fb.w+1)+x;
            let [fr,fg,fb_]=fb.fg[idx];
            let ch=fb.ch[idx];
            write!(w,"\x1b[48;2;{BG};{BG};{BG}m\x1b[38;2;{fr};{fg};{fb_}m{}\x1b[49m\x1b[39m",ch as char).unwrap();
        }
    }
}

fn output_html<W:Write>(w:&mut W, fb:&Buf) {
    for y in 0..fb.h {
        for x in 0..=fb.w {
            let idx=y*(fb.w+1)+x;
            let [r,g,b]=fb.fg[idx];
            let ch=fb.ch[idx];
            if ch==b'\n' { write!(w,"\n").unwrap(); }
            else { write!(w,"<span style=\"color:rgb({r},{g},{b})\">{}", ch as char).unwrap(); }
        }
    }
}

fn terminal_size() -> (usize,usize) {
    #[repr(C)] struct Ws{r:u16,c:u16,_p:u32}
    extern "C" { fn ioctl(fd:i32,req:u64,...)->i32; }
    let mut ws=Ws{r:0,c:0,_p:0};
    let ret=unsafe{ioctl(1,0x5413u64,&mut ws as *mut Ws)};
    if ret==0&&ws.c>0&&ws.r>0{(ws.c as usize,ws.r as usize)}else{(80,24)}
}

fn parse_args(args:&[String]) -> (f32,f32,f32,Vec<String>,Option<String>,Option<usize>,Option<usize>,Option<usize>) {
    let (mut rx,mut ry,mut rz)=(0.0f32,0.0f32,0.0f32);
    let mut files=vec![];
    let mut sub=None;
    let (mut iw,mut ih,mut wf)=(None::<usize>,None::<usize>,None::<usize>);
    let mut i=0; let mut in_sub=false;
    while i<args.len() {
        let a=&args[i];
        if in_sub {
            match a.as_str() {
                "--help"=>{print_img_help();std::process::exit(0);}
                "-b"=>{}
                "-w"=>{i+=1;if i<args.len(){iw=args[i].parse().ok();}}
                "-h"=>{i+=1;if i<args.len(){ih=args[i].parse().ok();}}
                "-j"|"--webify"=>{i+=1;if i<args.len(){wf=args[i].parse().ok();}}
                "-x"|"--yaw"=>{i+=1;if i<args.len(){if let Ok(v)=args[i].parse(){rx=v;}}}
                "-y"|"--pitch"=>{i+=1;if i<args.len(){if let Ok(v)=args[i].parse(){ry=v;}}}
                "-z"|"--roll"=>{i+=1;if i<args.len(){if let Ok(v)=args[i].parse(){rz=v;}}}
                _=>{}
            }
        } else {
            match a.as_str() {
                "--help"|"-h"=>{print_help();std::process::exit(0);}
                "--version"|"-V"=>{println!("Sloth 0.1");std::process::exit(0);}
                "-b"=>{}
                "-x"|"--yaw"=>{i+=1;if i<args.len(){if let Ok(v)=args[i].parse(){rx=v;}}}
                "-y"|"--pitch"=>{i+=1;if i<args.len(){if let Ok(v)=args[i].parse(){ry=v;}}}
                "-z"|"--roll"=>{i+=1;if i<args.len(){if let Ok(v)=args[i].parse(){rz=v;}}}
                "image" if !files.is_empty()=>{sub=Some("image".into());in_sub=true;}
                "help"=>{print_help();std::process::exit(0);}
                _=>{files.push(a.clone());}
            }
        }
        i+=1;
    }
    (rx,ry,rz,files,sub,iw,ih,wf)
}

fn main() {
    let argv:Vec<String>=std::env::args().skip(1).collect();
    if argv.is_empty(){print_help();return;}
    let (rx,ry,rz,files,sub,iw,ih,wf)=parse_args(&argv);
    if files.is_empty(){print_help();return;}

    let mut model=Model{vertices:vec![],normals:vec![],faces:vec![],materials:vec![]};
    for fp in &files {
        for p in fp.split_whitespace() {
            if p.is_empty(){continue;}
            let m=load_obj(p);
            let (vo,no,mo)=(model.vertices.len(),model.normals.len(),model.materials.len());
            model.vertices.extend(m.vertices);
            model.normals.extend(m.normals);
            model.materials.extend(m.materials);
            for mut f in m.faces {
                for v in &mut f.vertices{*v+=vo;} for n in &mut f.normals{*n+=no;} f.material_idx+=mo;
                model.faces.push(f);
            }
        }
    }

    let out=io::stdout();
    let mut w=BufWriter::new(out.lock());
    match sub.as_deref() {
        Some("image") => {
            let width=iw.unwrap_or_else(||{eprintln!("error: -w required");std::process::exit(1);});
            let height=ih.unwrap_or(width);
            if let Some(n)=wf {
                write!(w,"let frames = [\n").unwrap();
                for fi in 0..n {
                    let theta=2.0*PI*fi as f32/n as f32;
                    let fb=render(&model,rx,ry+theta,rz,width,height);
                    write!(w,"`\n").unwrap();
                    output_html(&mut w,&fb);
                    if fi<n-1{write!(w," `,\n").unwrap();}else{write!(w," `];\n").unwrap();}
                }
            } else {
                let fb=render(&model,rx,ry,rz,width,height);
                output_ansi(&mut w,&fb);
            }
        }
        _ => {
            let (tw,th)=terminal_size();
            let fb=render(&model,rx,ry,rz,tw,th);
            output_ansi(&mut w,&fb);
        }
    }
    w.flush().unwrap();
}

