import re, subprocess

# Frame 0: both mine and ref show purple '#' and red '#' ✓
# Let me check more frames:

mine = subprocess.run(['./sloth_impl/target/debug/sloth', 'assets/test_model.obj', 'image', '-w', '20', '-h', '20', '-j', '36'],
                     capture_output=True, text=True)
ref = subprocess.run(['./executable', 'assets/test_model.obj', 'image', '-w', '20', '-h', '20', '-j', '36'],
                    capture_output=True, text=True)

def parse_frames(output):
    lines = output.split('\n'); frames=[]; cur=[]; inf=False
    for line in lines:
        if line=='`' and not inf: inf=True
        elif line.endswith('`,'):
            cur.append(line[:-2]); frames.append(cur); cur=[]; inf=False
        elif line.endswith('`];'):
            cur.append(line[:-3]); frames.append(cur); inf=False
        elif inf and line: cur.append(line)
    return frames

def get_dominant_chars(frame):
    chars_by_color = {}
    for line in frame:
        for r,g,b,c in re.findall(r'rgb\((\d+),(\d+),(\d+)\)">(.)(?=<|$)', line):
            key = (int(r),int(g),int(b))
            if key != (0,0,0):
                if key not in chars_by_color: chars_by_color[key] = {}
                chars_by_color[key][c] = chars_by_color[key].get(c,0)+1
    return {k: max(v.items(), key=lambda x:x[1])[0] for k,v in chars_by_color.items()}

mine_frames = parse_frames(mine.stdout)
ref_frames = parse_frames(ref.stdout)

matches = 0
total = min(len(mine_frames), len(ref_frames))
for fi in range(total):
    m_chars = get_dominant_chars(mine_frames[fi])
    r_chars = get_dominant_chars(ref_frames[fi])
    if m_chars == r_chars:
        matches += 1
    else:
        # Show what's different
        if fi < 5:
            print(f"Frame {fi}: mine={m_chars}, ref={r_chars}")

print(f"\nDominant char match: {matches}/{total}")
